import{_ as d,o as i,c as e,a4 as a}from"./chunks/framework.vNSRaLQv.js";const m=JSON.parse('{"title":"mybilibili 微服务基础设施恢复报告","description":"","frontmatter":{"title":"mybilibili 微服务基础设施恢复报告","date":"2026-06-26T00:00:00.000Z"},"headers":[],"relativePath":"posts/mybilibili 微服务基础设施恢复报告.md","filePath":"posts/mybilibili 微服务基础设施恢复报告.md"}'),l={name:"posts/mybilibili 微服务基础设施恢复报告.md"};function r(o,t,s,n,h,b){return i(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="mybilibili-微服务基础设施恢复报告" tabindex="-1">mybilibili 微服务基础设施恢复报告 <a class="header-anchor" href="#mybilibili-微服务基础设施恢复报告" aria-label="Permalink to &quot;mybilibili 微服务基础设施恢复报告&quot;">​</a></h1><h2 id="恢复时间" tabindex="-1">恢复时间 <a class="header-anchor" href="#恢复时间" aria-label="Permalink to &quot;恢复时间&quot;">​</a></h2><p>2026-06-26</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>因 Docker 目录迁移操作失误，导致 Docker 程序、WSL 虚拟磁盘（52GB）、Minio 视频数据全部丢失。本次工作完成 Docker 重装、目录迁移、镜像拉取、基础设施部署、数据恢复。</p><h2 id="一、docker-desktop-迁移" tabindex="-1">一、Docker Desktop 迁移 <a class="header-anchor" href="#一、docker-desktop-迁移" aria-label="Permalink to &quot;一、Docker Desktop 迁移&quot;">​</a></h2><h3 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>D:\\devtools\\Docker\\</span></span>
<span class="line"><span>├── App\\              (Docker Desktop 程序本体)</span></span>
<span class="line"><span>├── Images\\           (WSL 虚拟磁盘)</span></span>
<span class="line"><span>└── Volumes\\          (持久化数据)</span></span></code></pre></div><h3 id="迁移方式" tabindex="-1">迁移方式 <a class="header-anchor" href="#迁移方式" aria-label="Permalink to &quot;迁移方式&quot;">​</a></h3><ol><li>正常安装 Docker Desktop 到 C 盘</li><li>停止所有 Docker 进程和 WSL</li><li>将 C:\\Program Files\\Docker 移动到 D:\\devtools\\Docker\\App</li><li>创建 Junction 符号链接：C:\\Program Files\\Docker → D:\\devtools\\Docker\\App</li><li>配置 settings-store.json 的 CustomWslDistroDir 指向 D:\\devtools\\Docker\\Images</li></ol><h3 id="关键教训" tabindex="-1">关键教训 <a class="header-anchor" href="#关键教训" aria-label="Permalink to &quot;关键教训&quot;">​</a></h3><p><strong>绝对不能在符号链接内部执行文件操作。</strong> Junction 是透明的，你以为在操作 D 盘，实际通过链接操作的是 C 盘。正确流程：先断开链接 → 创建目录 → 复制文件 → 删除原目录 → 重建链接。</p><h2 id="二、镜像拉取" tabindex="-1">二、镜像拉取 <a class="header-anchor" href="#二、镜像拉取" aria-label="Permalink to &quot;二、镜像拉取&quot;">​</a></h2><table tabindex="0"><thead><tr><th>镜像</th><th>大小</th><th>用途</th></tr></thead><tbody><tr><td>mysql:5.7</td><td>700MB</td><td>数据库</td></tr><tr><td>redis:7.2-alpine</td><td>56.9MB</td><td>缓存</td></tr><tr><td>mongo:6.0</td><td>1.1GB</td><td>MongoDB</td></tr><tr><td>minio/minio:latest</td><td>241MB</td><td>对象存储</td></tr><tr><td>nacos/nacos-server:v2.3.2</td><td>1.27GB</td><td>服务注册中心</td></tr><tr><td>apache/rocketmq:4.9.7</td><td>-</td><td>消息队列</td></tr><tr><td>elasticsearch:7.17.18</td><td>1.02GB</td><td>搜索引擎</td></tr><tr><td>mybilibili-elasticsearch-ik:7.17.18</td><td>1.04GB</td><td>ES + IK 分词插件（自定义构建）</td></tr><tr><td>registry.cn-hangzhou.aliyuncs.com/ossrs/srs:5</td><td>224MB</td><td>流媒体服务器</td></tr></tbody></table><h3 id="镜像拉取问题" tabindex="-1">镜像拉取问题 <a class="header-anchor" href="#镜像拉取问题" aria-label="Permalink to &quot;镜像拉取问题&quot;">​</a></h3><p>Docker Desktop 跑在 WSL 里，WSL 是独立网络命名空间，Windows 系统代理对它无效。必须在 Docker Desktop GUI 里手动配置代理（Settings → Resources → Proxies → Manual configuration）。</p><h2 id="三、基础设施部署" tabindex="-1">三、基础设施部署 <a class="header-anchor" href="#三、基础设施部署" aria-label="Permalink to &quot;三、基础设施部署&quot;">​</a></h2><p>使用 <code>docker-compose-infra.yml</code> 部署 9 个服务：</p><table tabindex="0"><thead><tr><th>服务</th><th>容器名</th><th>端口</th><th>状态</th></tr></thead><tbody><tr><td>MySQL 5.7</td><td>mybilibili-mysql</td><td>3306</td><td>healthy</td></tr><tr><td>Redis 7.2</td><td>mybilibili-redis</td><td>6379</td><td>healthy</td></tr><tr><td>MongoDB 6.0</td><td>mybilibili-mongodb</td><td>27017</td><td>healthy</td></tr><tr><td>Minio</td><td>mybilibili-minio</td><td>9000/9001</td><td>healthy</td></tr><tr><td>Nacos</td><td>mybilibili-nacos</td><td>8848</td><td>healthy</td></tr><tr><td>Elasticsearch</td><td>mybilibili-elasticsearch</td><td>9200</td><td>healthy</td></tr><tr><td>RocketMQ Namesrv</td><td>mybilibili-rocketmq-namesrv</td><td>9876</td><td>running</td></tr><tr><td>RocketMQ Broker</td><td>mybilibili-rocketmq-broker</td><td>10911</td><td>running</td></tr><tr><td>SRS</td><td>mybilibili-srs</td><td>1935</td><td>running</td></tr></tbody></table><h3 id="部署前准备" tabindex="-1">部署前准备 <a class="header-anchor" href="#部署前准备" aria-label="Permalink to &quot;部署前准备&quot;">​</a></h3><ol><li>创建 .env 文件（MYSQL_ROOT_PASSWORD、MINIO_ROOT_USER、MINIO_ROOT_PASSWORD）</li><li>创建 Docker 网络 mybilibili-net</li><li>创建 Volumes 目录结构</li><li>更新 compose 文件中的卷路径（D:/DockerFiles/ → D:/devtools/Docker/Volumes/）</li></ol><h2 id="四、数据恢复" tabindex="-1">四、数据恢复 <a class="header-anchor" href="#四、数据恢复" aria-label="Permalink to &quot;四、数据恢复&quot;">​</a></h2><h3 id="mysql" tabindex="-1">MySQL <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;MySQL&quot;">​</a></h3><ul><li>备份文件：<code>D:\\files\\mybilibili-next\\mybilibili-cloud\\init\\mybilibili-mysql.sql</code>（96.4KB）</li><li>备份时间：2026-05-31</li><li>恢复方式：<code>docker exec -i mybilibili-mysql mysql -uroot -p&lt;password&gt; mybilibili &lt; mybilibili-mysql.sql</code></li><li>恢复结果：39 张表，完整数据</li></ul><h3 id="mongodb" tabindex="-1">MongoDB <a class="header-anchor" href="#mongodb" aria-label="Permalink to &quot;MongoDB&quot;">​</a></h3><ul><li>备份文件：<code>D:\\files\\mybilibili-next\\mybilibili-cloud\\init\\mybilibili-mongodb.sql</code>（188.9KB）</li><li>备份时间：2026-05-24</li><li>恢复方式：<code>docker exec mybilibili-mongodb mongosh mybilibili /tmp/restore.sql</code></li><li>恢复结果：2 个集合（danmakus: 15 docs, subtitles: 15 docs）</li></ul><h3 id="minio" tabindex="-1">Minio <a class="header-anchor" href="#minio" aria-label="Permalink to &quot;Minio&quot;">​</a></h3><ul><li>数据来源：<code>D:\\files\\mybilibili\\uploads\\</code>（本地残留目录）</li><li>上传方式：docker cp → mc cp --recursive</li><li>恢复结果：625 个文件 <ul><li>avatars: 2 个头像</li><li>covers: 1 个封面</li><li>images: 13 张图片</li><li>manuscripts: 609 个文件（源视频、转码片段、字幕、音频等）</li></ul></li></ul><h3 id="数据路径修正" tabindex="-1">数据路径修正 <a class="header-anchor" href="#数据路径修正" aria-label="Permalink to &quot;数据路径修正&quot;">​</a></h3><p>数据库中有 6 条视频记录的 source_video_url 和 play_url_hd 路径错误（manuscript_id 不匹配），已修正：</p><table tabindex="0"><thead><tr><th>video_id</th><th>修正前 manuscript</th><th>修正后 manuscript</th></tr></thead><tbody><tr><td>26</td><td>10</td><td>11</td></tr><tr><td>27</td><td>10</td><td>11</td></tr><tr><td>28</td><td>10</td><td>11</td></tr><tr><td>29</td><td>10</td><td>12</td></tr><tr><td>30</td><td>10</td><td>13</td></tr><tr><td>31</td><td>10</td><td>14</td></tr></tbody></table><h2 id="五、最终对齐检查" tabindex="-1">五、最终对齐检查 <a class="header-anchor" href="#五、最终对齐检查" aria-label="Permalink to &quot;五、最终对齐检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>总数</th><th>OK</th><th>缺失</th></tr></thead><tbody><tr><td>用户头像</td><td>2（本地）</td><td>2</td><td>0</td></tr><tr><td>稿件封面</td><td>9</td><td>9</td><td>0</td></tr><tr><td>视频源文件</td><td>11</td><td>11</td><td>0</td></tr><tr><td>转码播放地址</td><td>9</td><td>9</td><td>0</td></tr><tr><td>MongoDB danmakus</td><td>15</td><td>15</td><td>0</td></tr><tr><td>MongoDB subtitles</td><td>15</td><td>15</td><td>0</td></tr></tbody></table><p><strong>结论：100% 对齐，零丢失。</strong></p><h2 id="六、损失与恢复对比" tabindex="-1">六、损失与恢复对比 <a class="header-anchor" href="#六、损失与恢复对比" aria-label="Permalink to &quot;六、损失与恢复对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>丢失</th><th>恢复</th></tr></thead><tbody><tr><td>Docker Desktop 程序</td><td>✗ 删除</td><td>✓ 重装</td></tr><tr><td>WSL 虚拟磁盘（52GB）</td><td>✗ 删除</td><td>✓ 重建</td></tr><tr><td>容器镜像（9个）</td><td>✗ 删除</td><td>✓ 重新拉取</td></tr><tr><td>MySQL 数据库</td><td>✗ 删除</td><td>✓ 从备份恢复</td></tr><tr><td>MongoDB 数据库</td><td>✗ 删除</td><td>✓ 从备份恢复</td></tr><tr><td>Minio 视频数据</td><td>✗ 删除</td><td>✓ 从本地 uploads 恢复</td></tr><tr><td>n8n/dify/one-api 配置</td><td>✗ 删除</td><td>- 不恢复</td></tr></tbody></table><h2 id="七、文件清单" tabindex="-1">七、文件清单 <a class="header-anchor" href="#七、文件清单" aria-label="Permalink to &quot;七、文件清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>路径</th></tr></thead><tbody><tr><td>Docker 配置</td><td>C:\\Users\\a1\\AppData\\Roaming\\Docker\\settings-store.json</td></tr><tr><td>Docker daemon</td><td>C:\\Users\\a1.docker\\daemon.json</td></tr><tr><td>Compose 文件</td><td>D:\\files\\mybilibili-next\\mybilibili-cloud\\scripts\\docker-compose-infra.yml</td></tr><tr><td>环境变量</td><td>D:\\files\\mybilibili-next\\mybilibili-cloud\\scripts.env</td></tr><tr><td>MySQL 备份</td><td>D:\\files\\mybilibili-next\\mybilibili-cloud\\init\\mybilibili-mysql.sql</td></tr><tr><td>MongoDB 备份</td><td>D:\\files\\mybilibili-next\\mybilibili-cloud\\init\\mybilibili-mongodb.sql</td></tr><tr><td>本地 uploads</td><td>D:\\files\\mybilibili\\uploads\\</td></tr><tr><td>Docker Volumes</td><td>D:\\devtools\\Docker\\Volumes\\mybilibili\\</td></tr></tbody></table>`,38)])])}const p=d(l,[["render",r]]);export{m as __pageData,p as default};
